class Solution {
public:
    int magicalString(int n) {
        if (n <= 0) return 0;
        std::vector<int> a{1, 2, 2};
        int ones = 1, read = 2, next = 1;
        while ((int)a.size() < n) {
            int count = a[read++];
            for (int j = 0; j < count && (int)a.size() < n; ++j) {
                a.push_back(next);
                if (next == 1) ++ones;
            }
            next = 3 - next;
        }
        return ones;
    }
};
